-- GENERATED by `wfj generate` from data/gossip/gossip-a2.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["a2034f22e885b859"] = { "%s tira fuori una bottiglia piena di uno strano liquido verde e ne beve un gran sorso.", "." },
  ["a2040c5628cca5ab"] = { "Ah, senza dubbio un futuro guerriero! Immagino che tu partecipi alla Children's Week, vero? Scalda queste vecchie ossa sapere che stai dando l'esempio che altri di sicuro seguiranno.\n\nAccontenterò volentieri te e il ragazzino. Mmm... che consiglio dovrei dargli? Ascoltare gli spiriti, sì... e magari anche qualcosa sul mangiare tutte le verdure...", "." },
  ["a2076cc10c849d43"] = { "Quali sono le anomalie di cui parli?", "." },
  ["a20c349fe0df7302"] = { "Di solito trovi fratello Wilhelm sul retro della fucina, a scambiarsi storie con Lyria. È sempre pronto a insegnare nuove abilità ai suoi compagni paladini.", "." },
  ["a212fc0ec15af5a2"] = { "Il Cult of the Damned è cresciuto molto in estensione. Quasi ogni città, dalle capitali ai piccoli villaggi e tuguri dell'⟦Horde=Orda⟧ come dell'⟦Alliance=Alleanza⟧, ha membri del Culto nascosti tra i suoi cittadini.\n\nNon fare quella faccia sorpresa. Il Culto indossa un'uniforme solo per riti e cerimonie. È del tutto possibile che tu ne abbia incontrato uno durante le tue avventure senza nemmeno saperlo.", "." },
  ["a21cf8cb52e6ab06"] = { "Hai idea di quanto tempo è che aspetto qui? E la cena dov'è? Tutto questo tempo passato e niente in cambio?", "." },
  ["a22e42a9ad71206e"] = { "Non vedi che stiamo cercando di prepararci per la visita di Uther? Ora levati di torno, ho molto lavoro da fare!", "." },
  ["a23830cbb017c2f7"] = { "|cff33ccffTutte e quattro le torri sono ora sotto il controllo dell'⟦Alliance=Alleanza⟧!|r", "." },
  ["a238c9ae316b8c67"] = { "Niente male... per essere alle prime armi! Comunque ne sai quanto me. Se vuoi imparare di più, dovrai parlare con Josef Gregorian a ⟦Undercity=Sepulcra⟧.", "." },
  ["a24517f6174d770e"] = { "Il monastero era un tempo un centro di studio e di illuminazione. Con l'ascesa del Flagello dei non morti durante la Terza Guerra, il pacifico monastero fu trasformato in una roccaforte della fanatica ⟦Scarlet Crusade=Crociata Scarlatta⟧. I crociati non tollerano nessuna razza non umana, quali che siano le alleanze o le affiliazioni. Credono che tutti gli estranei, nessuno escluso, siano potenziali portatori della piaga dei non morti, e che vadano distrutti.", "." },
  ["a2468c97ffc277c5"] = { "Non si rendono conto di essere morti, {race}. Sono condannati a rivivere l'ultimo ricordo che avevano prima che il villaggio venisse divorato dall'interno. Quasi tutti, almeno. Alcuni sono stati meno fortunati.\n\nPensavi che fosse opera del Flagello? Il Flagello non esisteva ancora, e se fosse esistito, avremmo almeno combattuto, dannazione!\n\nNo, questo è stato il risultato di una pestilenza uscita da Scholomance che ha devastato il villaggio. È stato orribile e devastante. Nessuno è sopravvissuto.\n\nOra lasciami al mio dolore.", "." },
  ["a24bcbe61a6284a6"] = { "Ahhhh!!! Che cos'è quella cosa?!", "." },
  ["a250c471dcad571c"] = { "Vi spaccherò il cranio con tutta la potenza dei ⟦Blackrock=Roccianera⟧.", "." },
  ["a253aeaf2e7f8439"] = { "Pattugliate il ⟦Frost Dagger Pass=Passo di Lama del Gelo⟧. Non lasciate passare nessuno! Morite con onore...", "." },
  ["a25d250685c5828e"] = { "L'⟦Horde=Orda⟧ ha conquistato la ⟦Coldtooth Mine=Miniera di Dentefreddo⟧!", "." },
  ["a265c83918945f3d"] = { "{name}. Queste conchiglie mi dicono molto, ma temo che ora sorgano molte altre domande...", "." },
  ["a2674e8b9d9d2224"] = { "Guerrieri della notte... Adunata!", "." },
  ["a2684981e51693eb"] = { "Tutti hanno un punto debole, è solo questione di trovarlo.", "." },
  ["a26a5d8216680a75"] = { "Oh, quanto dolore...", "." },
  ["a26d7c5bf350d886"] = { "%s ha fame...", "." },
  ["a26e2aed4ecdb6c0"] = { "Come posso aiutarti?", "." },
  ["a2716eb2227017ee"] = { "Bene, pare che abbiamo tutte le alborelle iridate in carpione che possiamo salare e conservare a dovere per la guerra imminente ad ⟦Ahn'Qiraj=Ahn'qiraj⟧. Grazie comunque per avermelo chiesto, {class}. Se ti va, chiedi in giro agli altri raccoglitori. Scommetto che c'è qualcun altro qui a cui farebbe comodo il tuo aiuto per raccogliere quello che gli serve.", "." },
  ["a275c312e7ba0578"] = { "I nostri sentieri nella vita si incrociano solo per poco, e ora è il momento che si separino. È stata una benedizione per me passare questo tempo a insegnarti, e ora ti mando a incrociare il sentiero del tuo prossimo maestro. Cerca ⟦Saru Steelfury=Saru Furiaferro⟧ a Orgrimmar: ti insegnerà ciò che devi imparare.", "." },
  ["a277c2f983a7d82f"] = { "Terrore, oscurità, potere? I Reietti non bramano queste cose: i Reietti SONO queste cose.", "." },
  ["a280d381802bd2ed"] = { "Hai fatto un ottimo lavoro, Spybot! Sono felice di riaverti qui con me!", "." },
  ["a283c2f9db050264"] = { "Un altro sciocco cade per mano della ⟦Defias Brotherhood=Fratellanza dei Defias⟧.", "." },
  ["a288b23380aa2f13"] = { "Salute, {race}. Sono ⟦Franclorn Forgewright=Franclorn Forgiabruna⟧. Sei qui per sapere dei Bastioni e dei ⟦Dark Iron=Ferroscuro⟧?", "." },
  ["a295c6be6af11faf"] = { "sembra sul punto di andare in frantumi!", "." },
  ["a29c7dda8a511820"] = { "Quel folle sconsiderato di Mulverick mi ha abbattuto. Temo che, se non riesco a tornare alla base, sarà tutto perduto! Mulverick e la sua squadra di Calcaguerra vanno fermati!", "." },
  ["a29edf868120f52f"] = { "È meglio dei disegni nei tomi di storia.", "." },
  ["a2a01226dfe65ef6"] = { "Va bene, va bene... dammi un minuto per riposare. Me le hai suonate per bene.", "." },
  ["a2a0820b57e19010"] = { "Druidi? Non ho visto druidi da queste parti. C'è però un distretto di ⟦Stormwind=Roccavento⟧ che gli elfi della notte hanno fatto proprio.", "." },
  ["a2a9b112b63a4252"] = { "Mi dispiace, Leonid, ma devo rifiutare. Molto è cambiato, ma i Reietti sono ancora il popolo che abbiamo giurato di proteggere.", "." },
  ["a2b01da73756fef9"] = { "Prendetelo!", "." },
  ["a2b23d8a5bf0abb1"] = { "Ben trovati, viaggiatori di ⟦Duskwood=Boscovespro⟧! La mia incredibile merce è in vendita per poco tempo a ⟦Darkshire=Borgoscuro⟧. Affrettatevi!", "." },
  ["a2b4c01388511582"] = { "E ora la guerra, lei sta per arrivare. Resta solo da mandare tutte queste merci e armi alla ⟦Cenarion Hold=Fortezza Cenariana⟧ a ⟦Silithus=Silitus⟧, e sarà fatto entro un giorno. Poi qualche anima coraggiosa dovrà suonare il gong vicino alle porte di ⟦Ahn'Qiraj=Ahn'qiraj⟧ per aprirle e dare inizio alla guerra.", "." },
  ["a2bc248a107c6922"] = { "Sì, gestisco questo negozio da un po' di tempo. Gli affari vanno piuttosto bene ultimamente. Passano molti nuovi avventurieri...", "." },
  ["a2ccae0f96491199"] = { "Dove mi conduce ora il mio sentiero, Jorn?", "." },
  ["a2d1d95379ac1750"] = { "Qualcosa affligge questa torre. Mi è venuta una malattia, e anche gli altri dipendenti della S.P.R. & Co. che lavorano vicino o dentro la torre si sono ammalati. Proprio la settimana scorsa due delle nostre pattuglie sono morte, solo per tornare subito in vita come automi senza mente! La forza vitale mi sta abbandonando. Sento che sto perdendo il controllo. Impulsi che prendono il sopravvento... Impulsi malvagi... Non ancora... Ascolta... La mia è una posizione di potere. Questa posizione mi dà accesso ad alcune informazioni riservate.", "." },
  ["a2d46cd0d9ed9dbd"] = { "GOR'TESH MORTO?!?!", "." },
  ["a2d797c9f3cfa5d1"] = { "Col favore delle tenebre.", "." },
  ["a2da42935a43f438"] = { "La lettura è di 8536 gradi Kraklenheit... Ti sei già stancato di me?", "." },
  ["a2dc9f303157ad66"] = { "L'abbiamo portata dal comandante sperando che i druidi del Circolo potessero rimetterla in sesto. E infatti sono riusciti a svegliarla. Pensavamo che i nostri affari con il Circolo fossero chiusi e di poter tornare al lavoro.\n\nPassarono alcune settimane e tutto andava bene. Allora Brann era ancora qui, quindi nel lavoro c'era un minimo d'ordine. Poi un giorno, di punto in bianco, lei ricomparve al nostro accampamento.", "." },
  ["a2eb2d0f987f53b9"] = { "Bene! Vedo che i miei sforzi non andranno sprecati!", "." },
  ["a2eb364eb38403b5"] = { "Non c'è nient'altro che posso insegnarti. Ho sentito parlare di un'elfa della notte che forse può farlo, però. Si chiama Ainethil, e vive alla ⟦Craftsmen's Terrace=Terrazza degli Artigiani⟧ di Darnassus.", "." },
  ["a2f585cb399ac6a3"] = { "Neltharion, eh? Una risposta valida come un'altra, no?", "." },
})
